  /// <summary>
  /// Order filling type
  /// </summary>
  public enum OrderFilling {
    /// <summary>
    /// The FOK (Fill or Kill) policy indicates that an order can only be executed in the specified volume. If the necessary amount of a financial instrument is not currently available in the market, the order will not be executed. The required volume can be filled using several offers available at the moment.
    /// </summary>
    [pbr::OriginalName("ORDER_FILLING_FOK")] Fok = 0,
    /// <summary>
    /// The IOC (Immediate or Cancel) policy indicates that a deal can be executed in the maximum volume available in the market within the volume specified in the order. If the order cannot be filled completely, the available volume will be filled, and the remaining volume will be canceled.
    /// </summary>
    [pbr::OriginalName("ORDER_FILLING_IOC")] Ioc = 1,
    /// <summary>
    /// The Return policy is only used for market, Limit and Stop Limit orders. In case of partial filling, an order with the remaining volume is not canceled, but is processed further. This policy is not used for Stop and Stop Limit orders when they are activated.
    /// </summary>
    [pbr::OriginalName("ORDER_FILLING_RETURN")] Return = 2,
    /// <summary>
    /// The BOC (Book or Cancel) policy indicates that an order can only be placed in the Depth of Market. If the order can be executed immediately when placed, it is canceled. This policy is used for Limit orders.
    /// </summary>
    [pbr::OriginalName("ORDER_FILLING_BOC")] Boc = 3,
  }

